from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                            seen.add((ny, nx))
                            q.append((ny, nx))
            comps.append(cells)
    def bottom_run(cells):
        bottom = max(r for r, c in cells)
        xs = sorted(c for r, c in cells if r == bottom)
        return len(xs) if xs[-1] - xs[0] + 1 == len(xs) else 1000 + len(xs)
    cells = min(comps, key=bottom_run)
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    return [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
